#!/usr/bin/env bash
#
# Assemble the release bundle. The release page carries installers only:
#
#   nyist-connect.exe                         Windows GUI + updater payload
#   NYIST-Connect-macos-{amd64,arm64}.dmg      macOS app
#   nyist-connect_<ver>_{amd64,arm64}.deb      Linux (Debian/Ubuntu)
#   nyist-connect-<ver>-<rel>.{x86_64,aarch64}.rpm  Linux (Fedora/RHEL)
#   SHA256SUMS.txt                             covers every asset above
#
# AUR/Homebrew/MacPorts/Nix recipes, Arch packages, Flatpak/Snap manifests,
# repository metadata and shell completions are still generated by
# scripts/package-distributions.sh for maintainers, but they are not published
# here; regenerating them from the repository is the supported path.

set -euo pipefail
cd "$(dirname "$0")/.."

die() {
	printf 'package-release: %s\n' "$*" >&2
	exit 1
}

VERSION="${VERSION:-${GITHUB_REF_NAME:-${CI_COMMIT_TAG:-0.0.0-dev}}}"
version="${VERSION#v}"
[[ "$version" =~ ^[0-9]+\.[0-9]+\.[0-9]+([-+][0-9A-Za-z.-]+)?$ ]] ||
	die "invalid VERSION: $VERSION"
[[ "$version" =~ ^[A-Za-z0-9.+~_-]+$ ]] || die "unsafe VERSION: $VERSION"

dist="dist"
[[ -d "$dist" ]] || die "missing dist directory"

# Remove artifacts from older bundle layouts; these were published as separate
# release assets before and must never be picked up again.
rm -f "$dist"/README.md "$dist"/NYIST-CONNECT.md "$dist"/LICENSE "$dist"/PACKAGING.md
rm -f "$dist"/release-assets.txt "$dist"/SHA256SUMS.txt
rm -f "$dist"/authingnyist-*-extras-*.tar.gz

assets=(nyist-connect.exe)

# --- Windows GUI (must stay at the top level for internal/update/download.go) ---
[[ -s "$dist/nyist-connect.exe" && ! -L "$dist/nyist-connect.exe" ]] ||
	die "missing Windows GUI asset: nyist-connect.exe"

# --- macOS app bundles -------------------------------------------------------
macos_dmgs=()
for arch in amd64 arm64; do
	dmg="NYIST-Connect-macos-${arch}.dmg"
	if [[ -e "$dist/$dmg" ]]; then
		macos_dmgs+=("$dmg")
	fi
done
if ((${#macos_dmgs[@]} == 1)); then
	die "incomplete macOS DMG set (need both amd64 and arm64)"
fi
if [[ "${REQUIRE_MACOS_DMG:-0}" == 1 && ${#macos_dmgs[@]} -ne 2 ]]; then
	die "REQUIRE_MACOS_DMG=1 but the DMG set is incomplete"
fi
assets+=("${macos_dmgs[@]}")

# --- Linux packages (one deb per arch; RPM optional but must be complete) ----
debs=() rpms=()
if [[ -f "$dist/linux-assets.txt" ]]; then
	while IFS= read -r name; do
		[[ -n "$name" ]] || continue
		[[ "$name" =~ ^[A-Za-z0-9][A-Za-z0-9._+~-]*$ ]] ||
			die "invalid Linux asset name: $name"
		case "$name" in
			*.deb) debs+=("$name") ;;
			*.rpm) rpms+=("$name") ;;
			*) : ;; # Arch, AUR and other by-products are not published.
		esac
	done < "$dist/linux-assets.txt"
fi
((${#debs[@]} == 2)) || die "expected two .deb assets (amd64 and arm64), found ${#debs[@]}"
if ((${#rpms[@]})); then
	((${#rpms[@]} == 2)) || die "expected two .rpm assets (x86_64 and aarch64), found ${#rpms[@]}"
fi
# Counts alone would accept two builds of the same architecture.
printf '%s\n' "${debs[@]}" | grep -q '_amd64\.deb$' ||
	die "missing amd64 .deb in linux-assets.txt"
printf '%s\n' "${debs[@]}" | grep -q '_arm64\.deb$' ||
	die "missing arm64 .deb in linux-assets.txt"
if ((${#rpms[@]})); then
	printf '%s\n' "${rpms[@]}" | grep -q '\.x86_64\.rpm$' ||
		die "missing x86_64 .rpm in linux-assets.txt"
	printf '%s\n' "${rpms[@]}" | grep -q '\.aarch64\.rpm$' ||
		die "missing aarch64 .rpm in linux-assets.txt"
fi
assets+=("${debs[@]}" "${rpms[@]}")

# --- Validate every primary asset -------------------------------------------
for name in "${assets[@]}"; do
	path="$dist/$name"
	[[ -s "$path" ]] || die "missing or empty release asset: $name"
	[[ ! -L "$path" ]] || die "release asset must not be a symlink: $name"
done

# --- Checksums --------------------------------------------------------------
(
	cd "$dist"
	sha256sum "${assets[@]}" > SHA256SUMS.txt
	sha256sum --check --strict --quiet SHA256SUMS.txt
)

printf '%s\n' "${assets[@]}" SHA256SUMS.txt > "$dist/release-assets.txt"

bash scripts/check-release-assets.sh "$dist"
